Prob068_countbcd.code:
module TopModule (
    input  logic clk,
    input  logic reset,
    output logic [2:0] ena,
    output logic [15:0] q
);

// Internal registers for the four BCD digits
logic [3:0] ones;
logic [3:0] tens;
logic [3:0] hundreds;
logic [3:0] thousands;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        ones     <= 4'd0;
        tens     <= 4'd0;
        hundreds <= 4'd0;
        thousands <= 4'd0;
    end else begin
        // Ones digit: increments every clock cycle
        if (ones == 4'd9) begin
            ones <= 4'd0;
        end else begin
            ones <= ones + 1'd1;
        end

        // Tens digit: increments when ones rolls over from 9 to 0
        if (ones == 4'd9) begin
            if (tens == 4'd9) begin
                tens <= 4'd0;
            end else begin
                tens <= tens + 1'd1;
            end
        end

        // Hundreds digit: increments when tens rolls over from 9 to 0
        if (tens == 4'd9) begin
            if (hundreds == 4'd9) begin
                hundreds <= 4'd0;
            end else begin
                hundreds <= hundreds + 1'd1;
            end
        end

        // Thousands digit: increments when hundreds rolls over from 9 to 0
        if (hundreds == 4'd9) begin
            if (thousands == 4'd9) begin
                thousands <= 4'd0;
            end else begin
                thousands <= thousands + 1'd1;
            end
        end
    end
end

// Output assignments
// q[3:0]  = ones
// q[7:4]  = tens
// q[11:8] = hundreds
// q[15:12] = thousands
assign q = {thousands, hundreds, tens, ones};

// ena (3 bits)
// ena[0] enables increment of the tens digit (ones == 9)
// ena[1] enables increment of the hundreds digit (tens == 9)
// ena[2] enables increment of the thousands digit (hundreds == 9)
assign ena[0] = (ones == 4'd9);
assign ena[1] = (tens == 4'd9);
assign ena[2] = (hundreds == 4'd9);

endmodule

Prob074_ece241_2014_q4.code:
module TopModule (
    input  clk,
    input  x,
    output z
);

    // Flip-flop outputs
    reg q1, q2, q3;

    // Initialize flip-flops to zero (as per specification)
    initial begin
        q1 = 1'b0;
        q2 = 1'b0;
        q3 = 1'b0;
    end

    // First flip-flop: associated with XOR gate
    // D input = x XOR (its corresponding flip-flop output q1)
    always @(posedge clk) begin
        q1 <= x ^ q1;
    end

    // Second flip-flop: associated with AND gate
    // D input = x AND (complemented output of its corresponding flip-flop ~q2)
    always @(posedge clk) begin
        q2 <= x & ~q2;
    end

    // Third flip-flop: associated with OR gate
    // D input = x OR (complemented output of its corresponding flip-flop ~q3)
    always @(posedge clk) begin
        q3 <= x | ~q3;
    end

    // Three-input NOR gate: outputs Z
    // Z = NOR(q1, q2, q3)
    assign z = ~(q1 | q2 | q3);

endmodule

