module TopModule (
    input  [3:0] in,
    output [3:0] out_both,
    output [3:0] out_any,
    output [3:0] out_different
);

    // out_both: Each bit indicates if the corresponding input bit and its neighbour to the left (higher index) are '1'.
    // out_both[3] is set to 0 as in[3] has no neighbour to the left.
    assign out_both = {1'b0, (in[2] & in[3]), (in[1] & in[2]), (in[0] & in[1])};

    // out_any: Each bit indicates if any of the corresponding input bit and its neighbour to the right are '1'.
    // out_any[0] is set to 0 as in[0] has no neighbour to the right.
    assign out_any = {1'b0, (in[3] | in[2]), (in[2] | in[1]), (in[1] | in[0])};

    // out_different: Each bit indicates if the corresponding input bit is different from its neighbour to the left.
    // The vector is treated as wrapping around, so in[3]'s neighbour to the left is in[0].
    // By extension, the neighbour to the left of in[0] is in[1] to maintain the "higher index" relationship modulo 4.
    assign out_different = {(in[3] ^ in[0]), (in[2] ^ in[3]), (in[1] ^ in[2]), (in[0] ^ in[1])};

endmodule

Prob096_review2015_fsmseq.code:
module TopModule (
    input  logic clk,
    input  logic reset,
    input  logic data,
    output logic start_shifting
);

// State encoding
// S0:   Initial state, no part of the sequence matched
// S1:   Matched '1' (prefix of 1101)
// S11:  Matched '11' (prefix of 1101)
// S110: Matched '110' (prefix of 1101)
// S1101: Sequence '1101' found (absorbing state)
parameter S0   = 3'b000;
parameter S1   = 3'b001;
parameter S11  = 3'b010;
parameter S110 = 3'b011;
parameter S1101 = 3'b100;

// Present state and next state registers
reg [2:0] ps, ns;

// Next state logic (combinational)
always @(*) begin
    case (ps)
        S0:     ns = data ? S1 : S0;
        S1:     ns = !data ? S0 : S11;
        S11:    ns = !data ? S110 : S11; // '111' keeps us in S11 (overlapping suffix '11')
        S110:   ns = !data ? S0 : S1101; // '1100' goes to S0, '1101' goes to found
        S1101:  ns = S1101;                // Absorbing state: stay found forever
        default: ns = S0;
    endcase
end

// State update (synchronous reset, active high)
always @(posedge clk) begin
    if (reset)
        ps <= S0;
    else
        ps <= ns;
end

// Output logic: start_shifting is 1 once the sequence is detected
assign start_shifting = (ps == S1101);

endmodule

