Prob120_fsm3s.code:
module TopModule (
    input  logic clk,
    input  logic reset,
    input  logic in,
    output logic out
);

// State encoding: 2 bits
// 2'b00 = A, 2'b01 = B, 2'b10 = C, 2'b11 = D
logic [1:0] state, next_state;

// State register (synchronous active-high reset)
always @(posedge clk) begin
    if (reset)
        state <= 2'b00;   // reset to state A
    else
        state <= next_state;
end

// Next-state logic (Moore machine)
always @(*) begin
    case (state)
        2'b00: // State A
            next_state = in ? 2'b01 : 2'b00; // in=1 -> B, in=0 -> A
        2'b01: // State B
            next_state = in ? 2'b01 : 2'b10; // in=1 -> B, in=0 -> C
        2'b10: // State C
            next_state = in ? 2'b11 : 2'b00; // in=1 -> D, in=0 -> A
        2'b11: // State D
            next_state = in ? 2'b01 : 2'b10; // in=1 -> B, in=0 -> C
        default: next_state = 2'b00;
    endcase
end

// Output logic (Moore: output depends only on state)
assign out = (state == 2'b11) ? 1'b1 : 1'b0;

endmodule

