module TopModule (
    input  clk,
    input  reset,
    input  x,
    output z
);

    reg [2:0] y;          // state register, y[2:0]
    reg [2:0] y_next;     // next-state register

    // combinational next-state logic
    always @(*) begin
        case (y)
            3'b000: y_next = (x == 1'b1) ? 3'b001 : 3'b000;
            3'b001: y_next = (x == 1'b1) ? 3'b100 : 3'b001;
            3'b010: y_next = (x == 1'b1) ? 3'b001 : 3'b010;
            3'b011: y_next = (x == 1'b1) ? 3'b010 : 3'b001;
            3'b100: y_next = (x == 1'b1) ? 3'b100 : 3'b011;
            default:  y_next = 3'b000;   // unused states (101, 110, 111)
        endcase
    end

    // output logic: z = 1 only in states 011 and 100
    assign z = (y == 3'b011) || (y == 3'b100) ? 1'b1 : 1'b0;

    // sequential logic: positive-edge clock, synchronous active-high reset
    always @(posedge clk) begin
        if (reset)
            y <= 3'b000;
        else
            y <= y_next;
    end

endmodule

