// Top-level module with exactly the specified ports
module TopModule (
    input  logic x,
    input  logic y,
    output logic z
);

    // Internal wires connecting submodules and gates
    wire a1_out, b1_out, a2_out, b2_out;
    wire or_out, and_out;

    // First A and B submodules: both receive top-level x and y
    A u_a1 (.x(x), .y(y), .z(a1_out));
    B u_b1 (.x(x), .y(y), .z(b1_out));

    // Second A and B submodules: both receive top-level x and y
    A u_a2 (.x(x), .y(y), .z(a2_out));
    B u_b2 (.x(x), .y(y), .z(b2_out));

    // OR gate: first A output OR first B output
    assign or_out = a1_out | b1_out;

    // AND gate: second A output AND second B output
    assign and_out = a2_out & b2_out;

    // XOR gate: OR output XOR AND output -> z
    assign z = or_out ^ and_out;

endmodule

