module TopModule(
    input clk,
    input reset,
    input [2:0] s,
    output reg fr0,
    output reg fr1,
    output reg fr2,
    output reg dfr
);

reg [2:0] prev_s;

always @(posedge clk) begin
    if (reset) begin
        fr0 <= 1'b1;
        fr1 <= 1'b1;
        fr2 <= 1'b1;
        dfr <= 1'b1;
        prev_s <= 3'b000;
    end else begin
        case (s)
            3'b111: begin
                fr0 <= 1'b0;
                fr1 <= 1'b0;
                fr2 <= 1'b0;
                dfr <= 1'b0;
            end
            3'b011: begin
                fr0 <= 1'b1;
                fr1 <= 1'b0;
                fr2 <= 1'b0;
                dfr <= (prev_s < s) ? 1'b1 : 1'b0;
            end
            3'b001: begin
                fr0 <= 1'b1;
                fr1 <= 1'b1;
                fr2 <= 1'b0;
                dfr <= (prev_s < s) ? 1'b1 : 1'b0;
            end
            3'b000: begin
                fr0 <= 1'b1;
                fr1 <= 1'b1;
                fr2 <= 1'b1;
                dfr <= 1'b1;
            end
            default: begin
                fr0 <= fr0;
                fr1 <= fr1;
                fr2 <= fr2;
                dfr <= dfr;
            end
        endcase
        prev_s <= s;
    end
end

endmodule
